// Simple application - hardened for security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Security headers (helmet sets X-Frame-Options, X-Content-Type-Options,
//    Content-Security-Policy, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing with a strict size limit to prevent payload-based DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Global rate limiter – max 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check – no sensitive data, safe to leave public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list – add query-param validation as an example
app.get('/users', (req, res, next) => {
  try {
    // Example input validation: optional ?limit= param must be a safe integer
    const { limit } = req.query;

    if (limit !== undefined) {
      const parsed = parseInt(limit, 10);
      if (isNaN(parsed) || parsed < 1 || parsed > 100) {
        return res.status(400).json({
          error: 'Invalid "limit" parameter. Must be an integer between 1 and 100.',
        });
      }
    }

    // TODO: replace with real DB query + authentication check
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const result = limit ? users.slice(0, parseInt(limit, 10)) : users;
    res.json(result);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 4. 404 handler – catches any unmatched routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 5. Global error handler – must have exactly 4 parameters for Express to
//    recognise it as an error-handling middleware.
//    Never expose stack traces to the client in production.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';

  console.error(`[${new Date().toISOString()}] ERROR:`, err);

  res.status(err.status || 500).json({
    error: err.message || 'Internal server error.',
    // Only include stack trace in non-production environments
    ...(isDev && { stack: err.stack }),
  });
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
  });
}

module.exports = app;

