'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ─── Security Headers ────────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, Content-Security-Policy, etc.
app.use(helmet());

// ─── Body Parsing ────────────────────────────────────────────────────────────
// Limit payload size to prevent large-body DoS attacks.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── Rate Limiting ───────────────────────────────────────────────────────────
// Applies to all routes; prevents brute-force and DoS attacks.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,     // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── Health Check ────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── Users ───────────────────────────────────────────────────────────────────
// Static data shown here; in production this would come from a database.
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

/**
 * GET /users
 * Optional query param: ?name=<string> (alpha + spaces, max 50 chars)
 *
 * Input validation prevents injection and unexpected behaviour if this route
 * is later wired to a real data source.
 */
app.get('/users', (req, res, next) => {
  try {
    const { name } = req.query;

    // Validate optional `name` query parameter.
    if (name !== undefined) {
      if (typeof name !== 'string' || name.length > 50) {
        return res.status(400).json({
          error: 'Invalid query parameter: "name" must be a string of at most 50 characters.',
        });
      }
      // Allow only letters and spaces to prevent injection characters.
      if (!/^[a-zA-Z\s]+$/.test(name)) {
        return res.status(400).json({
          error: 'Invalid query parameter: "name" may only contain letters and spaces.',
        });
      }

      const filtered = USERS.filter((u) =>
        u.name.toLowerCase().includes(name.toLowerCase())
      );
      return res.json(filtered);
    }

    res.json(USERS);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler.
  }
});

// ─── 404 Handler ─────────────────────────────────────────────────────────────
// Must be defined after all valid routes.
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ─── Global Error Handler ────────────────────────────────────────────────────
// The four-argument signature is required by Express to treat this as an
// error-handling middleware. Never expose stack traces to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log internally for diagnostics (replace with a proper logger in production).
  // Sanitize the message to prevent log-injection attacks.
  const safeMessage = String(err.message).replace(/[\r\n]/g, ' ');
  console.error(`[ERROR] ${new Date().toISOString()} - ${safeMessage}`);

  // Return a generic message so internal details are never leaked to clients.
  res.status(err.status || 500).json({ error: 'An unexpected error occurred.' });
});

// ─── Server Bootstrap ────────────────────────────────────────────────────────
// Read the port from the environment so it is configurable per deployment.
const PORT = parseInt(process.env.PORT || '3000', 10);

const server = app.listen(PORT, () => {
  // Only log the environment type, not internal hostnames or secrets.
  const env = process.env.NODE_ENV || 'development';
  console.log(`Server running on port ${PORT} [${env}]`);
});

module.exports = { app, server };

