  try {
    const users = await getUsersFromDB(); // Replace with real data source
    res.json(users);
  } catch (err) {
    next(err); // Delegate to the global error handler
  }
});
```

---

### 6. 🌍 Hardcoded Port
**Problem:** Port `3000` is hardcoded, making environment-specific configuration impossible.

**Fix:** Read from environment variables with a sensible fallback.
```js
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### 7. 🔒 No CORS Policy
**Problem:** Without explicit CORS rules, cross-origin behaviour is unpredictable and potentially permissive.

**Fix:** Use the [`cors`](https://www.npmjs.com/package/cors) package with an allowlist.
```js
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  methods: ['GET', 'POST'],
}));
