'use strict';

const express = require('express');
const helmet = require('helmet');               // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const { body, query, validationResult } = require('express-validator'); // Input validation

const app = express();

// ─── Configuration ────────────────────────────────────────────────────────────
// Always read sensitive config from environment variables, never hardcode them.
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ─── Security Headers (helmet) ────────────────────────────────────────────────
// Sets headers like Content-Security-Policy, X-Frame-Options, X-DNS-Prefetch-Control,
// Strict-Transport-Security, etc., to defend against common web vulnerabilities.
app.use(helmet());

// ─── Body Parsing with Size Limit ─────────────────────────────────────────────
// Limit payload size to prevent denial-of-service via large request bodies.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── Global Rate Limiting ─────────────────────────────────────────────────────
// Prevents brute-force attacks, credential stuffing, and DoS by limiting how
// many requests a single IP can make in a given window.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // Max 100 requests per IP per window
  standardHeaders: true,     // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,      // Disable deprecated `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ─── Request Logger ───────────────────────────────────────────────────────────
// A minimal audit log. In production, replace with a structured logger (e.g. winston/pino).
app.use((req, _res, next) => {
  const { method, url, ip } = req;
  // Avoid logging sensitive data such as Authorization headers or request bodies.
  console.log(`[${new Date().toISOString()}] ${method} ${url} — IP: ${ip}`);
  next();
});

// ─── Helper: Validation Error Responder ───────────────────────────────────────
// Centralises how validation errors are returned so routes stay clean.
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // 422 Unprocessable Entity is the most semantically correct status here.
    return res.status(422).json({ errors: errors.array() });
  }
  next();
};

// ─── Routes ───────────────────────────────────────────────────────────────────

// GET /health
// No user input is consumed here, so validation is not required.
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users
// Accepts optional `page` and `limit` query params for pagination.
// Validates and sanitises them before use.
app.get(
  '/users',
  [
    query('page')
