// Simple application with security best practices applied

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
// helmet sets a suite of protective HTTP headers automatically, including:
// X-Content-Type-Options, X-Frame-Options, Strict-Transport-Security, etc.
app.use(helmet());

// ─── 2. CORS ─────────────────────────────────────────────────────────────────
// Restrict cross-origin requests to known, trusted origins only.
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow server-to-server requests (no origin) only in non-production environments.
      if (!origin && process.env.NODE_ENV !== 'production') return callback(null, true);
      if (ALLOWED_ORIGINS.includes(origin)) return callback(null, true);
      callback(new Error(`CORS policy: origin '${origin}' is not allowed`));
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
);

// ─── 3. BODY PARSING & SIZE LIMITS ──────────────────────────────────────────
// Limit body size to prevent large-payload DoS attacks.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── 4. RATE LIMITING ────────────────────────────────────────────────────────
// Apply a global rate limit to all routes to mitigate brute-force and DoS attacks.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,     // return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ─── 5. REQUEST LOGGING (lightweight structured logging) ────────────────────
// Replace with a proper logger (e.g. winston, pino) in production.
app.use((req, _res, next) => {
  const { method, path, ip } = req;
  // Avoid logging sensitive query params or headers in production.
  console.log(JSON.stringify({ timestamp: new Date().toISOString(), method, path, ip }));
  next();
});

// ─── 6. ROUTES ───────────────────────────────────────────────────────────────

// Health check — deliberately minimal; does not expose internal state.
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users — return only non-sensitive fields; add authentication in production.
// WARNING: In a real app, protect this route with an auth middleware
//          (e.g. JWT verification) before it reaches this handler.
app.get('/users', (_req, res) => {
  // Simulated DB result — only expose fields that are safe for the caller.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Project only the fields the API consumer actually needs.
  const safeUsers = users.map(({ id, name }) => ({ id, name }));
  res.json(safeUsers);
});

// ─── 7. 404 HANDLER ──────────────────────────────────────────────────────────
// Catch requests to undefined routes before they reach the error handler.
app.use((_req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ─── 8. GLOBAL ERROR HANDLER ─────────────────────────────────────────────────
// Must have exactly 4 parameters so Express recognises it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Never leak stack traces or internal details to the client.
  console.error(JSON.stringify({ timestamp: new Date().toISOString(), error: err.message, stack: err.stack }));

  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' ? 'An unexpected error occurred.' : err.message,
  });
});

// ─── 9. UNHANDLED REJECTION / EXCEPTION GUARDS ───────────────────────────────
// Prevent silent failures that could leave the server in a broken state.
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Promise Rejection:', reason);
  // In production, consider a graceful shutdown here.
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1); // Mandatory exit — state is now undefined.
});

// ─── 10. SERVER STARTUP ───────────────────────────────────────────────────────
// Read port from environment so the app is portable across environments.
const PORT = parseInt(process.env.PORT || '3000', 10);

const server = app.listen(PORT, () => {
  console.log(JSON.stringify({ event: 'server_start', port: PORT, env: process.env.NODE_ENV || 'development' }));
});

// Graceful shutdown — drain existing connections before exiting.
const shutdown = (signal) => {
  console.log(`${signal} received. Closing HTTP server…`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });
};
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;
